/**
 * `Env` is generated by `wrangler types` from wrangler.jsonc. These bindings are optional
 * (each one switches a feature on), so they are not declared in the config file: they come
 * from `wrangler secret put`, .dev.vars, or an uncommented `send_email` binding.
 */
export interface OptionalEnv {
  /** Google sign-in is offered when both are set. */
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  /** "1" enables POST /api/auth/dev, and only for requests to localhost. Set it in .dev.vars only. */
  DEV_AUTH?: string;
  /** Cloudflare Email Sending binding; magic-link sign-in needs it and EMAIL_FROM. */
  EMAIL?: SendEmail;
  EMAIL_FROM?: string;
}

// Omit: `wrangler types` also reads .dev.vars and would declare whatever is set there as always present.
export type AppEnv = Omit<Env, keyof OptionalEnv> & OptionalEnv;

export interface Ctx {
  request: Request;
  url: URL;
  env: AppEnv;
  exec: ExecutionContext;
  params: Record<string, string>;
  now: number;
}
